pub fn commit_turn(
    &self,
    turn: &Turn,
    tasks: &[TurnTask],
    key: Option<&str>,
    legacy_tasks: &[Task],
) -> Result<Turn> {
    validate_turn_input(turn, tasks, key)?;
    let mut db = self.db.lock().unwrap();
    let tx = db.transaction()?;
    if let Some(existing) = self.commit_turn_in_tx(&tx, turn, tasks, key, legacy_tasks)? {
        return Ok(existing);
    }
    tx.commit()?;
    Ok(turn.clone())
}
